SELECT * FROM store.pos_lines LIMIT 5;
SELECT * FROM payments.pos_payments LIMIT 5;
SELECT DISTINCT note FROM payments.pos_payments LIMIT 30;
SELECT DISTINCT tender FROM payments.pos_payments;
SELECT DISTINCT till_status FROM payments.pos_payments;

SELECT * FROM store.store_orders ORDER BY created_ts LIMIT 20;
SELECT * FROM store.write_offs ORDER BY date LIMIT 20;
SELECT * FROM store.stock_counts ORDER BY count_ts LIMIT 25;

SELECT min(date), max(date), count(*) FROM store.daily_sales;
SELECT * FROM store.daily_sales ORDER BY date, sku LIMIT 15;
SELECT * FROM store.forecasts ORDER BY date, sku LIMIT 15;
SELECT * FROM store.inventory_book ORDER BY date, sku LIMIT 15;

SELECT min(date) mn, max(date) mx, count(*) n, count(DISTINCT date) d, count(DISTINCT sku) s FROM store.forecasts;
SELECT min(date) mn, max(date) mx, count(*) n, count(DISTINCT date) d, count(DISTINCT sku) s FROM store.inventory_book;
SELECT * FROM store.forecasts ORDER BY date, sku LIMIT 12;
SELECT * FROM store.inventory_book ORDER BY date, sku LIMIT 12;

SELECT date_trunc('day', bill_ts)::date d, unit_price, count(*) lines, sum(qty) qty
FROM store.pos_lines WHERE sku_scanned='ATTA-WW-5KG'
GROUP BY 1,2 ORDER BY 1,2;

SELECT * FROM store.goods_receipts ORDER BY received_ts LIMIT 15;
SELECT receipt_method, count(*) FROM store.goods_receipts GROUP BY 1;
SELECT * FROM warehouse.shipments ORDER BY dispatched_ts LIMIT 10;
